def run_batch_and_log(use_azure: bool = True) -> None:
    """Run summarization over SAMPLE_TRANSCRIPTS and write to logs file.

    If Azure is requested but not available, it falls back to offline summarizer.
    """
    azure = AzureSummarizer()
    offline = OfflineSummarizer()

    if use_azure and azure.available:
        summarizer_name = "Azure OpenAI"
        summarize_fn = azure.summarize
    else:
        summarizer_name = "Offline Heuristic"
        summarize_fn = offline.summarize

    outputs: List[str] = []
    for i, t in enumerate(SAMPLE_TRANSCRIPTS, start=1):
        try:
            summary = summarize_fn(t)
        except Exception as e:
            summary = f"[Error summarizing transcript {i}: {e}]\n\nFalling back to Offline summarizer.\n\n" + offline.summarize(t)
        block = (
            f"==== Sample {i} | Engine: {summarizer_name} ===="
            f"\nTranscript:\n{textwrap.indent(t, '  ')}\n\nSummary:\n{textwrap.indent(summary, '  ')}\n\n"
        )
        outputs.append(block)

    with open(LOGS_FILE, "w", encoding="utf-8") as f:
        f.write("AI-Powered Meeting Summarizer — Batch Results\n")
        f.write(f"API Version: {API_VERSION_DEFAULT}\n")
        f.write(f"Azure Available: {AzureSummarizer().available}\n\n")
        for block in outputs:
            f.write(block)


def main() -> None:
    # No interactive input; runs on dummy samples by default
    run_batch_and_log(use_azure=True)
    print(f"Done. Wrote summaries to {LOGS_FILE}")


if __name__ == "__main__":
    main()
